(()=>{
const M=SACCR,{m,n,pct,slider,select,bars,add}=SACCR_UI;
add({id:'saccr-ir',name:'Interest-rate add-on',stage:'03 · Asset-class laboratories',title:'Rate offsets depend on currency and maturity bucket',intro:'Rate trades are grouped by currency, then assigned to three end-date buckets. Opposite positions in different buckets receive partial offset.',chart:'Bucket risk positions and the rate add-on',inputs:[slider('a','0.5-year trade · signed notional',-200,200,5,100),slider('b','3-year trade · signed notional',-200,200,5,-80),slider('c','10-year trade · signed notional',-200,200,5,30),select('currency','Currency arrangement',[['same','All GBP'],['split','10-year trade in EUR']],'same'),select('margin','Maturity treatment',[['no','Unmargined'],['yes','Margined · assumed valid 10-day MPOR']],'no')],challenge:'Move the long-dated trade to another currency. Why does the cross-currency offset disappear?',formula:'Dk = Σtrade δ × adjusted notional × MF\nEffective notional = √(D1² + D2² + D3² + 1.4 D1D2 + 1.4 D2D3 + 0.6 D1D3)\nAdd-on per ordinary rate hedging set = 0.5% × effective notional\nCurrency hedging-set add-ons are summed',key:'End-date buckets: (0,1], (1,5], and greater than 5 years. Signed notional represents a linear trade with delta +1 or −1. This is not a vega or curvature calculation.',simple:'A short-term rate position is an imperfect hedge for a long-term one. The bucket formula recognises that imperfection. Moving a trade to another currency creates another hedging set whose add-on is added.',scope:'Three constant-notional, already-started linear trades with end dates 0.5, 3 and 10 years. Adjusted notional uses supervisory duration. No inflation, basis or volatility hedging sets.',rule:'Articles 277a, 279–279c and 280a',compute(s){const ts=[.5,3,10],ns=[s.a,s.b,s.c],ds=ns.map((x,i)=>x*M.sd(0,ts[i])*M.mf(ts[i],10,s.margin==='yes')),k=s.currency==='same'?M.ir(ds):M.ir([ds[0],ds[1],0])+M.ir([0,0,ds[2]]);return {stats:[['IR add-on',m(k)],['Currency sets',s.currency==='same'?'1':'2'],['Supervisory factor','0.50%']],bars:bars(['Bucket 1 position','Bucket 2 position','Bucket 3 position','IR add-on'],[...ds,k]),headers:['Trade','Signed notional','Duration','MF','Risk position'],rows:ts.map((t,i)=>[t+' years',m(ns[i]),n(M.sd(0,t)),n(M.mf(t,10,s.margin==='yes')),m(ds[i])]),explanation:'The rate add-on is '+m(k)+'. The positions in the table already include duration and maturity-factor adjustments. '+(s.currency==='same'?'The three GBP buckets enter one correlation formula.':'GBP and EUR add-ons are calculated independently and added.'),note:'Interest-rate add-ons are summed across currency and other required hedging sets.'};}});
add({id:'saccr-fx',name:'Foreign-exchange add-on',stage:'03 · Asset-class laboratories',title:'FX offsets stop at the currency-pair boundary',intro:'Transactions with the same currency pair share an FX hedging set. The add-on uses the absolute net risk position, with a 4% supervisory factor.',chart:'Same-pair offset versus separate pairs',inputs:[slider('a','Trade A · signed adjusted notional',-200,200,5,100),slider('b','Trade B · signed adjusted notional',-200,200,5,-80),select('pair','Currency pairs',[['same','Both EUR / GBP'],['different','EUR / GBP and USD / GBP']],'same'),slider('years','Common remaining maturity',.05,3,.05,1,'years')],challenge:'Match opposite notionals, then change one currency pair. Can the perfect offset survive?',formula:'Risk position = δ × adjusted notional × MF\nFX add-on = Σpairs 4% × |Σ risk positions within pair|',key:'Adjusted notionals are expressed in reporting-currency millions. For two non-reporting-currency legs, use the larger converted leg; when one leg is in reporting currency, use the other leg, converted.',simple:'An offset in one exchange rate does not remove exposure to another exchange rate. SA-CCR permits netting inside the specified pair, then adds the absolute add-ons across pairs.',scope:'Two ordinary linear FX transactions, unmargined, with common remaining maturity. The sliders are adjusted notionals after currency conversion, with signs representing delta. No basis or volatility hedging sets.',rule:'Articles 277a(1)(b), 279b(1)(b) and 280b',compute(s){const mf=M.mf(s.years,0,false),a=s.a*mf,b=s.b*mf,same=.04*Math.abs(a+b),separate=.04*(Math.abs(a)+Math.abs(b)),k=s.pair==='same'?same:separate;return {stats:[['FX add-on',m(k)],['Maturity factor',n(mf)],['Pair sets',s.pair==='same'?'1':'2']],bars:bars(['Trade A position','Trade B position','Same-pair add-on','Separate-pair add-on'],[a,b,same,separate]),headers:['Component','Result'],rows:[['A risk position',m(a)],['B risk position',m(b)],['Selected aggregation',s.pair==='same'?'Net then absolute value':'Absolute values then sum'],['Selected FX add-on',m(k)]],explanation:'The selected FX add-on is '+m(k)+'. Same-pair netting gives '+m(same)+', while separate pairs give '+m(separate)+'. The difference comes from the hedging-set boundary.',note:'The FX supervisory factor is 4% here; do not substitute the SA-CVA FX weight.'};}});
const entityLab=(credit)=>{
 const id=credit?'saccr-credit':'saccr-equity';
 add({id,name:credit?'Credit add-on':'Equity add-on',stage:'03 · Asset-class laboratories',title:credit?'Reference-entity risk remains after a credit hedge':'An index and a single stock have different supervisory treatment',intro:'Net risk positions within a reference entity first. Across distinct entities, the formula combines a common-factor term with entity-specific residual risk.',chart:'Signed entity contributions and aggregate add-on',
 inputs:[slider('a','Position A · signed risk position',-200,200,5,100),slider('b','Position B · signed risk position',-200,200,5,-80),select('group','Reference-entity arrangement',[['distinct','Two distinct reference entities'],['same','Same reference entity']],'distinct'),select('kind','Reference instrument',credit?[['single','Single-name credit'],['index','Quoted credit index']]:[['single','Single equity'],['index','Equity index / multi-name']],'single'),...(credit?[select('quality','Credit quality',[[1,'CQS 1 / index IG'],[2,'CQS 2 / index IG'],[3,'CQS 3 / index IG'],[4,'CQS 4 / index non-IG'],[5,'CQS 5 / index non-IG'],[6,'CQS 6 / index non-IG']].map(([v,l])=>[String(v),l]),'3')]:[])],
 challenge:'Use equal and opposite positions in two distinct entities. Then select the same entity. Why does the residual change?',
 formula:'Entity contribution Ak = supervisory factor × net risk position of entity k\nHedging-set add-on = √[(Σρk Ak)² + Σ(1 − ρk²)Ak²]',
 key:'ρ = 50% for single-name entities and 80% for multi-name entities. These are factor loadings, not a direct 50% or 80% pairwise correlation. For identical loadings, implied cross-entity correlation is ρ².',
 simple:'Two different issuers share market risk but can also move for their own reasons. The common-factor part can offset; the residual term preserves the risk of those differences. Exact matching inside the same reference entity nets before this formula.',
 scope:'Inputs are signed trade risk positions after delta, adjusted notional and MF. Both entries use the selected type and quality. No special hedging-set coefficient. The index choice assumes the relevant grouping conditions; quoted credit-index classification uses majority constituent quality.',
 rule:credit?'Article 280c':'Article 280d',
 reference:{headers:['Reference type','Supervisory factor','Factor loading'],rows:credit?[['CQS 1 / 2 / 3','0.38 / 0.42 / 0.54%','50%'],['CQS 4 / 5 / 6','1.06 / 1.6 / 6%','50%'],['Quoted index IG / non-IG','0.38 / 1.06%','80%']]:[['Single-name equity','32%','50%'],['Multi-name equity','20%','80%']]},
 notes:credit?[['Reference issuer versus trading counterparty','The credit factor here concerns the underlying reference issuer. It is not the risk weight of the derivative trading counterparty. For unrated or unquoted multi-name exposures, Article 280c(5) supplies additional mapping rules.']]:[],
 compute(s){const single=s.kind==='single',sf=credit?(single?[.0038,.0042,.0054,.0106,.016,.06][Number(s.quality)-1]:Number(s.quality)<=3?.0038:.0106):single?.32:.20,rho=single?.5:.8,positions=s.group==='same'?[s.a+s.b]:[s.a,s.b],a=positions.map(v=>v*sf),r=M.factor(a,a.map(()=>rho));return {stats:[['Asset-class add-on',m(r.addon)],['Supervisory factor',pct(sf)],['Factor loading',pct(rho)]],bars:bars(['Position A weighted','Position B weighted','Combined add-on'],[s.a*sf,s.b*sf,r.addon]),headers:['Calculation','Value','Units'],rows:[['Net entity positions',positions.map(m).join(' / '),'£m'],['Signed entity contributions',a.map(m).join(' / '),'£m'],['Common-factor term squared',n(r.sys*r.sys),'£m²'],['Entity-specific term',n(r.idio),'£m²'],['Square root of sum',m(r.addon),'Add-on']],explanation:'The add-on is '+m(r.addon)+'. '+(s.group==='same'?'Both positions net within one reference entity before the factor formula.':'The two entities retain residual risk even where their common-factor exposures offset.'),note:'Add this non-negative charge to other asset-class add-ons; no cross-class offset is applied.'};}});
};
entityLab(true);entityLab(false);
add({id:'saccr-commodity',name:'Commodity add-on',stage:'03 · Asset-class laboratories',title:'Commodity type and sector determine the offset',intro:'Risk positions net within a commodity reference type. Different types in one hedging set receive partial offset; different commodity hedging sets are added.',chart:'Commodity contributions and combined add-on',inputs:[slider('a','Commodity A · signed risk position',-200,200,5,100),slider('b','Commodity B · signed risk position',-200,200,5,-80),select('profile','Commodity arrangement',[['same','Same oil reference type'],['energy','Oil and natural gas · energy set'],['electric','Electricity and natural gas · energy set'],['split','Oil and gold · separate sets']],'energy')],challenge:'Compare an oil hedge with the same oil type, natural gas and gold. Which risk differences remain?',formula:'Ak = SFk × net risk position of commodity type k\nWithin set: √[(0.4 ΣAk)² + (1 − 0.4²)ΣAk²]\nCommodity add-on = sum of hedging-set add-ons',key:'SF = 40% for electricity and 18% for other commodities. Factor loading is 40%, giving a 16% pairwise cross term correlation within an ordinary set.',simple:'Not all commodities respond to the same news. Two oil contracts of the same reference type can offset more fully than oil and gas. Moving to a different sector removes the within-set offset altogether.',scope:'Already adjusted trade risk positions; ordinary hedging sets only. Reference types are based on underlying nature, irrespective of delivery location and quality, under Article 280e(2). These labels represent simplified types rather than a full commodity taxonomy.',rule:'Articles 277a(1)(e) and 280e',notes:[['PRA commodity hedging sets','Energy, metals, agricultural goods, other commodities and climatic conditions are separate hedging sets. Do not import FRTB or SA-CVA commodity buckets.']],compute(s){const sa=s.profile==='electric'?.4:.18,a=s.a*sa,b=s.b*.18,k=s.profile==='same'?Math.abs(a+b):s.profile==='split'?Math.abs(a)+Math.abs(b):M.factor([a,b],[.4,.4]).addon;return {stats:[['Commodity add-on',m(k)],['A supervisory factor',pct(sa)],['B supervisory factor','18.00%']],bars:bars(['A contribution','B contribution','Combined add-on'],[a,b,k]),headers:['Component','Amount','Treatment'],rows:[['A contribution',m(a),pct(sa)+' × risk position'],['B contribution',m(b),'18% × risk position'],['Aggregation',s.profile==='same'?'Same type':s.profile==='split'?'Separate sets':'Distinct types in energy','Prescribed grouping'],['Add-on',m(k),'Non-negative exposure allowance']],explanation:'The commodity add-on is '+m(k)+'. '+(s.profile==='same'?'The two trades net within the same reference type.':s.profile==='split'?'Energy and metals charges are added without cross-set offset.':'Different energy types receive partial common-factor offset and retain residual risk.'),note:'Risk position already includes supervisory delta, adjusted notional and maturity factor.'};}});
add({id:'saccr-other',name:'Other risks and special sets',stage:'03 · Asset-class laboratories',title:'Basis and volatility trades need their own hedging sets',intro:'Other-risk positions share a hedging set only with an identical primary driver. Special sets use a supervisory-factor coefficient of 0.5 for qualifying basis and 5 for volatility or correlation risk.',chart:'How the hedging-set coefficient changes the add-on',inputs:[slider('a','Position A · signed risk position',-200,200,5,100),slider('b','Position B · signed risk position',-200,200,5,-60),select('set','Prescribed hedging-set type',[['ordinary','Ordinary · coefficient 1'],['basis','Qualifying basis · coefficient 0.5'],['vol','Volatility / correlation · coefficient 5']],'ordinary'),select('same','Driver grouping',[['yes','Same eligible driver / pair'],['no','Different drivers / pairs']],'yes')],challenge:'Hold the risk positions constant and change set type. Why must the trade classification be justified before using the coefficient?',formula:'Other-risk add-on = Σεj × 8% × |Σ risk positions in set j|\nε = 1 ordinary; 0.5 qualifying basis; 5 volatility / correlation',key:'Basis and volatility coefficients also apply to their respective special sets in other asset classes. They are not freely selectable discounts or penalties for ordinary trades.',simple:'A bet on the difference between two related drivers is not the same as a bet on either driver alone. A volatility trade concerns a different risk again. The framework isolates these risks before applying the appropriate coefficient.',scope:'Illustrative already-calculated risk positions in the other-risk category. The controls assume the chosen trade type meets Article 277a(2), including the driver/pair grouping conditions. The example does not derive risk positions for a variance swap.',rule:'Articles 277a(2), 280 and 280f',compute(s){const e=s.set==='basis'?.5:s.set==='vol'?5:1,base=.08*(s.same==='yes'?Math.abs(s.a+s.b):Math.abs(s.a)+Math.abs(s.b)),k=e*base;return {stats:[['Other-risk add-on',m(k)],['Set coefficient',e.toFixed(1)],['Base supervisory factor','8.00%']],bars:bars(['Ordinary coefficient','Basis coefficient','Volatility coefficient'],[base,.5*base,5*base]),headers:['Component','Result'],rows:[['Grouping',s.same==='yes'?'One set':'Two sets'],['Add-on before coefficient',m(base)],['Selected coefficient',e],['Selected add-on',m(k)]],explanation:'The selected add-on is '+m(k)+'. The coefficient is '+e+', applied after netting only within the permitted hedging-set boundary. Classification follows the trade’s actual risk driver.',note:'A basis set requires the specified identical pair of positively correlated drivers; otherwise the rule supplies a different mapping.'};}});
})();

